-- Per-student, evidence-linked SAT coaching notes. Not generated by keyword classification.
-- Only the owning student can read the report. Authoring is restricted to
-- trusted administrative workflows; users cannot edit coaching evaluations.
create table if not exists public.sat_pretest_coaching (
  user_id uuid primary key references auth.users(id) on delete cascade,
  analysis jsonb not null,
  based_on_attempt_at timestamptz,
  reviewed_at timestamptz not null default now(),
  constraint sat_pretest_coaching_analysis_object check (jsonb_typeof(analysis)='object')
);
alter table public.sat_pretest_coaching enable row level security;
drop policy if exists sat_pretest_coaching_read_own on public.sat_pretest_coaching;
create policy sat_pretest_coaching_read_own on public.sat_pretest_coaching
  for select to authenticated using ((select auth.uid())=user_id);
revoke all on public.sat_pretest_coaching from anon,authenticated;
grant select on public.sat_pretest_coaching to authenticated;
comment on table public.sat_pretest_coaching is
  'Private individualized SAT pre-test coaching snapshot, supported by saved attempt data. Runtime category stats are independent and remain fresh.';